u32:n -> ??
nslots -> n * 4 + 16
mask -> nslots - 1
Idx -> 0..mask
Slots -> {...({u8:} * nslots):}
f -> {
  Slots:slots -> ??
  Idx:idx -> 0
  -> slots.#idx ? {
    0 -> 1
    -> f{slots -> slots  idx -> (idx + 1) [&] mask}!
  }
}
Slots:s -> ??
p -> f{slots -> s  idx -> 3 [&] mask}!
u8:q -> p
